class Items(_Resource):
    """Items are the content agents produce and humans review."""

    def list(
        self,
        *,
        collection: str | None = None,
        collection_id: str | None = None,
        status: str | None = None,
        decision: str | Sequence[str] | None = None,
        run: str | Sequence[str] | None = None,
        tag: str | Sequence[str] | None = None,
        archived: bool | None = None,
        run_action: str | None = None,
        type: str | None = None,
        q: str | None = None,
        source: str | None = None,
        external_ref: str | None = None,
        created_after: TimeFilter | None = None,
        created_before: TimeFilter | None = None,
        decided_after: TimeFilter | None = None,
        decided_before: TimeFilter | None = None,
        sort: str | None = None,
        limit: int | None = None,
        cursor: str | None = None,
        request_options: RequestOptions | None = None,
    ) -> ItemPage:
        """One page of items. ``collection`` accepts an ID or a name (resolved with one request).

        ``sort``: relevance, created_desc (default), created_asc, updated_desc,
        updated_asc, decided_desc, title_asc. ``limit``: 1-200 (default 50).
        ``decision`` (pending, approved, rejected, expired, archived), ``run`` (none,
        processing, completed, failed) and ``tag`` take one value or several (any of them);
        ``archived=False`` leaves archived items out; ``run_action`` (e.g. ``"publish"``, or
        ``"none"``) keeps runs started by that action.
        """
        if collection:
            collection_id = self._client.collections.resolve_id(collection, request_options=request_options)
        params = {
            "collection_id": collection_id,
            "status": status,
            "decision": _csv(decision),
            "run": _csv(run),
            "tag": _csv(tag),
            "archived": None if archived is None else ("true" if archived else "false"),
            "run_action": run_action,
            "type": type,
            "q": q,
            "source": source,
            "external_ref": external_ref,
            "created_after": created_after,
            "created_before": created_before,
            "decided_after": decided_after,
            "decided_before": decided_before,
            "sort": sort,
            "limit": limit,
            "cursor": cursor,
        }
        r = self._http.request(RequestSpec("GET", "/v1/items", params=params, options=_opts(request_options)))
        return _model(ItemPage, r)

    def search(
        self,
        q: str,
        *,
        collection: str | None = None,
        collection_id: str | None = None,
        status: str | None = None,
        type: str | None = None,
        sort: str | None = None,
        limit: int | None = None,
        cursor: str | None = None,
        request_options: RequestOptions | None = None,
    ) -> ItemPage:
        """Full-text search (prefix match over title, content and metadata), best match first."""
        return self.list(
            q=q,
            collection=collection,
            collection_id=collection_id,
            status=status,
            type=type,
            sort=sort,
            limit=limit,
            cursor=cursor,
            request_options=request_options,
        )

    def iterate(
        self,
        *,
        collection: str | None = None,
        collection_id: str | None = None,
        status: str | None = None,
        type: str | None = None,
        q: str | None = None,
        source: str | None = None,
        external_ref: str | None = None,
        created_after: TimeFilter | None = None,
        created_before: TimeFilter | None = None,
        decided_after: TimeFilter | None = None,
        decided_before: TimeFilter | None = None,
        sort: str | None = None,
        limit: int | None = None,
        cursor: str | None = None,
        request_options: RequestOptions | None = None,
    ) -> Iterator[Item]:
        """Yields every matching item, fetching pages lazily (``limit`` is the page size)."""
        if collection:
            collection_id = self._client.collections.resolve_id(collection, request_options=request_options)
        while True:
            page = self.list(
                collection_id=collection_id,
                status=status,
                type=type,
                q=q,
                source=source,
                external_ref=external_ref,
                created_after=created_after,
                created_before=created_before,
                decided_after=decided_after,
                decided_before=decided_before,
                sort=sort,
                limit=limit,
                cursor=cursor,
                request_options=request_options,
            )
            for item in page.data:
                yield item
            if not page.next_cursor:
                return
            cursor = page.next_cursor

    def get(self, item_id: str, *, request_options: RequestOptions | None = None) -> Item:
        r = self._http.request(RequestSpec("GET", f"/v1/items/{_q(item_id)}", options=_opts(request_options)))
        return _model(Item, r)

