class Webhooks(_Resource):
    """Signed HTTP callbacks for events (at-least-once). Verify them with :func:`staqly.verify_webhook`."""

    def __init__(self, client: Staqly) -> None:
        super().__init__(client)
        self.deliveries = Deliveries(client)

    def list(self, *, request_options: RequestOptions | None = None) -> builtins.list[Webhook]:
        r = self._http.request(RequestSpec("GET", "/v1/webhooks", options=_opts(request_options)))
        return _models(Webhook, r)

    def get(self, webhook_id: str, *, request_options: RequestOptions | None = None) -> Webhook:
        r = self._http.request(
            RequestSpec("GET", f"/v1/webhooks/{_q(webhook_id)}", options=_opts(request_options))
        )
        return _model(Webhook, r)

    def create(
        self,
        url: str,
        *,
        events: Sequence[str] | None = None,
        description: str | None = None,
        collection_ids: Sequence[str] | None = None,
        active: bool | None = None,
        timeout_ms: int | None = None,
        max_attempts: int | None = None,
        request_options: RequestOptions | None = None,
    ) -> Webhook:
        """Creates a webhook. ``events`` are names or globs (``"item.*"``, default ``["*"]``);
        the response carries the generated signing ``secret``."""
        body = clean(
            {
                "url": url,
                "events": list(events) if events is not None else None,
                "description": description,
                "collection_ids": list(collection_ids) if collection_ids is not None else None,
                "active": active,
                "timeout_ms": timeout_ms,
                "max_attempts": max_attempts,
            }
        )
        r = self._http.request(RequestSpec("POST", "/v1/webhooks", json=body, options=_opts(request_options)))
        return _model(Webhook, r)

    def update(
        self,
        webhook_id: str,
        *,
        url: str | None = None,
        events: Sequence[str] | None = None,
        description: str | None = None,
        collection_ids: Sequence[str] | None = None,
        active: bool | None = None,
        timeout_ms: int | None = None,
        max_attempts: int | None = None,
        rotate_secret: bool | None = None,
        request_options: RequestOptions | None = None,
    ) -> Webhook:
        body = clean(
            {
                "url": url,
                "events": list(events) if events is not None else None,
                "description": description,
                "collection_ids": list(collection_ids) if collection_ids is not None else None,
                "active": active,
                "timeout_ms": timeout_ms,
                "max_attempts": max_attempts,
                "rotate_secret": rotate_secret,
            }
        )
        r = self._http.request(
            RequestSpec("PATCH", f"/v1/webhooks/{_q(webhook_id)}", json=body, options=_opts(request_options))
        )
        return _model(Webhook, r)

    def rotate_secret(self, webhook_id: str, *, request_options: RequestOptions | None = None) -> Webhook:
        """Issues a new signing secret (the old one stops working immediately)."""
        return self.update(webhook_id, rotate_secret=True, request_options=request_options)

    def delete(self, webhook_id: str, *, request_options: RequestOptions | None = None) -> None:
        self._http.request(
            RequestSpec("DELETE", f"/v1/webhooks/{_q(webhook_id)}", options=_opts(request_options))
        )

    def test(self, webhook_id: str, *, request_options: RequestOptions | None = None) -> Delivery:
        """Queues a ``webhook.test`` delivery."""
        r = self._http.request(
            RequestSpec("POST", f"/v1/webhooks/{_q(webhook_id)}/test", options=_opts(request_options))
        )
        return _model(Delivery, r)


# ------------------------------------------------------------------- watchers


def _collections(collection: str | Sequence[str] | None) -> dict[str, object]:
    """One collection goes as ``collection``, several as ``collections``."""
    if collection is None:
        return {}
    if isinstance(collection, str):
        return {"collection": collection}
    return {"collections": list(collection)}


class Watchers(_Resource):
    """Watchers turn RSS feeds and web pages into items on a schedule."""

    def list(self, *, request_options: RequestOptions | None = None) -> builtins.list[Watcher]:
        r = self._http.request(RequestSpec("GET", "/v1/watchers", options=_opts(request_options)))
        return _models(Watcher, r)

    def get(self, watcher_id: str, *, request_options: RequestOptions | None = None) -> Watcher:
        r = self._http.request(
            RequestSpec("GET", f"/v1/watchers/{_q(watcher_id)}", options=_opts(request_options))
        )
        return _model(Watcher, r)

    def create(
        self,
        name: str,
        *,
        url: str,
        collection: str | Sequence[str],
        kind: str | None = None,
        keywords: Sequence[str] | None = None,
        exclude_keywords: Sequence[str] | None = None,
        every: str | None = None,
        request_options: RequestOptions | None = None,
    ) -> Watcher:
        """Creates a watcher. ``kind``: ``rss`` or ``url_diff``, left out to detect it from the URL (a feed is
        ``rss``, anything else ``url_diff``); ``collection``: ID or name, or several (each new entry
        is added to every one);
        ``every``: e.g. ``"30m"``, ``"6h"`` (plan minimums apply)."""
        body = clean(
            {
                "name": name,
                "kind": kind,
                "url": url,
                **_collections(collection),
                "keywords": list(keywords) if keywords is not None else None,
                "exclude_keywords": list(exclude_keywords) if exclude_keywords is not None else None,
                "every": every,
            }
        )
        r = self._http.request(RequestSpec("POST", "/v1/watchers", json=body, options=_opts(request_options)))
        return _model(Watcher, r)

    def update(
        self,
        watcher_id: str,
        *,
        name: str | None = None,
        kind: str | None = None,
        url: str | None = None,
        collection: str | Sequence[str] | None = None,
        keywords: Sequence[str] | None = None,
        exclude_keywords: Sequence[str] | None = None,
        every: str | None = None,
        status: str | None = None,
        request_options: RequestOptions | None = None,
    ) -> Watcher:
        body = clean(
            {
                "name": name,
                "kind": kind,
                "url": url,
                **_collections(collection),
                "keywords": list(keywords) if keywords is not None else None,
                "exclude_keywords": list(exclude_keywords) if exclude_keywords is not None else None,
                "every": every,
                "status": status,
            }
        )
        r = self._http.request(
            RequestSpec("PATCH", f"/v1/watchers/{_q(watcher_id)}", json=body, options=_opts(request_options))
        )
        return _model(Watcher, r)

    def pause(self, watcher_id: str, *, request_options: RequestOptions | None = None) -> Watcher:
        return self.update(watcher_id, status="paused", request_options=request_options)

    def resume(self, watcher_id: str, *, request_options: RequestOptions | None = None) -> Watcher:
        return self.update(watcher_id, status="active", request_options=request_options)

    def delete(self, watcher_id: str, *, request_options: RequestOptions | None = None) -> None:
        self._http.request(
            RequestSpec("DELETE", f"/v1/watchers/{_q(watcher_id)}", options=_opts(request_options))
        )

    def run(self, watcher_id: str, *, request_options: RequestOptions | None = None) -> WatcherRunResult:
        """Checks the source now instead of waiting for the schedule."""
        r = self._http.request(
            RequestSpec("POST", f"/v1/watchers/{_q(watcher_id)}/run", options=_opts(request_options))
        )
        return _model(WatcherRunResult, r)


