class Sessions(_Resource):
    """Browser (dashboard) sessions. Listing and revoking need ``admin``."""

    def current(self, *, request_options: RequestOptions | None = None) -> Whoami:
        """Server mode, workspace, the calling principal and the CSRF token (same as ``whoami()``)."""
        r = self._http.request(RequestSpec("GET", "/v1/session", options=_opts(request_options)))
        return _model(Whoami, r)

    def list(self, *, request_options: RequestOptions | None = None) -> builtins.list[Session]:
        r = self._http.request(RequestSpec("GET", "/v1/sessions", options=_opts(request_options)))
        return _models(Session, r)

    def revoke(self, session_id: str, *, request_options: RequestOptions | None = None) -> None:
        self._http.request(
            RequestSpec("DELETE", f"/v1/sessions/{_q(session_id)}", options=_opts(request_options))
        )

    def logout(self, *, request_options: RequestOptions | None = None) -> None:
        """Revokes the current session (``DELETE /v1/session``)."""
        self._http.request(RequestSpec("DELETE", "/v1/session", options=_opts(request_options)))

    def sign_in_with_api_key(
        self, api_key: str, *, request_options: RequestOptions | None = None
    ) -> SessionCreated:
        """Cloud mode: exchanges an ``admin`` API key (the key sign-up or ``recover()`` returns)
        for a session cookie (kept in the client's cookie jar). Sent without credentials (the key
        goes in the body); other sessions stay signed in. Keys without ``admin`` raise
        :class:`~staqly.PermissionDeniedError` (403), unknown, revoked or expired keys
        :class:`~staqly.AuthenticationError` (401), local mode :class:`~staqly.ConflictError` (409)."""
        r = self._http.request(
            RequestSpec(
                "POST",
                "/v1/sessions/api-key",
                json={"api_key": api_key},
                no_auth=True,
                options=_opts(request_options),
            )
        )
        return _model(SessionCreated, r)

    def recover(
        self, recovery_key: str, *, request_options: RequestOptions | None = None
    ) -> SessionRecovered:
        """Exchanges the recovery key (single use) for a new session cookie (kept in the client's
        cookie jar), a new admin API key and the next recovery key. The old recovery key stops
        working and every other session of the workspace is signed out; existing API keys keep
        working, except on Free, where the new admin key replaces the old admin keys. Sent without
        credentials. Store ``api_key.key`` and ``recovery_key`` now: they
        are shown only once."""
        r = self._http.request(
            RequestSpec(
                "POST",
                "/v1/sessions/recover",
                json={"recovery_key": recovery_key},
                no_auth=True,
                options=_opts(request_options),
            )
        )
        return _model(SessionRecovered, r)


